  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C40"],
      "claim": "Ketoprofen, a benzoyl aryl carboxylic acid NSAID closely related to the query, has absolute oral bioavailability exceeding 90% versus i.v. in humans, directly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Tiaprofenic acid, another benzoyl carboxylic acid NSAID, is almost completely absorbed after oral administration with bioavailability about 90–100%, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is ketorolac, an acidic benzoyl-pyrrolizine carboxylic acid NSAID. The closest relevant analogues, ketoprofen and tiaprofenic acid, share the benzoyl and carboxylic acid pharmacophore and show high absolute oral bioavailability (84–100%) in humans despite being ionized at physiological pH. Low-F evidence comes from structurally dissimilar molecules (indoramin, cocaine, fentanyl) and does not transfer. Therefore predict high F (≥20%).",
  "evidence_gaps": [
    "No direct experimental bioavailability record for ketorolac is present in the supplied evidence.",
    "Morgan similarities to the supporting analogues are low, so structural transfer relies on shared NSAID pharmacophore rather than high fingerprint overlap.",
    "No ketorolac-specific data on transporters, efflux, or first-pass metabolism are provided."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

